class Unquote(unittest.TestCase):
    def test_real_quoted_answers_survive(self):
        for src, raw in QUOTED:
            self.assertTrue(tf.is_source_echo(src, raw, "hi"), "fixture must be an echo before")
            out = tf.strip_leading_source_echo(src, raw, "hi")
            self.assertNotEqual(out, raw)
            self.assertFalse(tf.is_source_echo(src, out, "hi"), out)
            self.assertGreater(len(out), 20)

    def test_pure_echo_is_left_for_the_echo_test(self):
        src = "\u0930\u093e\u092e\u094b \u0935\u0928\u0902 \u0917\u091a\u094d\u091b\u0924\u093f \u0965"
        self.assertEqual(tf.strip_leading_source_echo(src, src, "hi"), src)
        self.assertTrue(tf.is_source_echo(src, src, "hi"))

    def test_plain_translation_untouched(self):
        src = "\u0930\u093e\u092e\u094b \u0935\u0928\u0902 \u0917\u091a\u094d\u091b\u0924\u093f \u0965"
        hi = "\u0930\u093e\u092e \u0935\u0928 \u0915\u094b \u091c\u093e\u0924\u093e \u0939\u0948\u0964 //"
        self.assertEqual(tf.strip_leading_source_echo(src, hi, "hi"), hi)
        en = "Rama goes to the forest. //"
        self.assertEqual(tf.strip_leading_source_echo(src, en, "en"), en)

    def test_english_after_quoted_source(self):
        src = "\u0930\u093e\u092e\u094b \u0935\u0928\u0902 \u0917\u091a\u094d\u091b\u0924\u093f \u0965"
        self.assertEqual(tf.strip_leading_source_echo(src, src + "\nRama goes to the forest. //", "en"),
                         "Rama goes to the forest. //")


if __name__ == "__main__":
    unittest.main()
